import pytest
from hypothesis import given, strategies as st
from solution import is_simple_power


# ---------- obviously-correct reference model ----------
def ref(x, n):
    # x == 1 is n**0 == 1 (Python: 0**0 == 1 as well)
    if x == 1:
        return True
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    if n == 0:
        # 0**k == 0 for k>=1, 0**0==1 handled above, 0**negative raises
        return x == 0
    # |n| >= 2 : negative exponents give non-integral floats, never equal int x
    # only need k >= 1 (k==0 handled by x==1 case)
    p = n
    while abs(p) <= abs(x):
        if p == x:
            return True
        # guard against overflow / unbounded loop; Python big ints exact
        # if next multiply would exceed and n doesn't divide, break is implicit
        # by abs growth for |n|>=2
        p = p * n
        # safety: prevent infinite loop in reference itself
        if abs(p) > 10**18 and abs(x) < 10**18:
            # p magnitude strictly grows for |n|>=2, so once past |x| we stop
            pass
    return False


# ---------- spec examples ----------
@pytest.mark.parametrize(
    "x,n,exp",
    [
        (1, 4, True),
        (2, 2, True),
        (8, 2, True),
        (3, 2, False),
        (3, 1, False),
        (5, 3, False),
    ],
)
def test_spec_examples(x, n, exp):
    assert is_simple_power(x, n) is exp or is_simple_power(x, n) == exp


def test_one_is_power_of_anything():
    for n in [-5, -2, -1, 0, 1, 2, 4, 100]:
        assert is_simple_power(1, n) is True or is_simple_power(1, n) == True


def test_n_one():
    assert is_simple_power(1, 1) == True
    assert is_simple_power(2, 1) == False
    assert is_simple_power(0, 1) == False
    assert is_simple_power(-1, 1) == False


def test_n_minus_one_minus_one():
    # (-1)**1 == -1 and (-1)**0 == 1
    assert is_simple_power(-1, -1) == True


def test_n_minus_one_one():
    assert is_simple_power(1, -1) == True


def test_n_minus_one_zero_is_false():
    assert is_simple_power(0, -1) == False


def test_n_minus_one_two_is_false():
    assert is_simple_power(2, -1) == False
    assert is_simple_power(-2, -1) == False


def test_zero_base_zero_exp():
    # 0**1 == 0
    assert is_simple_power(0, 0) == True


def test_one_base_zero():
    assert is_simple_power(1, 0) == True


# ---------- n == 0 hang / correctness via subprocess isolation ----------
import multiprocessing as _mp


def _target(x, n, q):
    try:
        q.put(("ok", is_simple_power(x, n)))
    except BaseException as e:  # noqa
        q.put(("exc", repr(e)))


def _assert_in_subprocess(x, n, expected):
    q = _mp.Queue()
    p = _mp.Process(target=_target, args=(x, n, q))
    p.start()
    p.join(timeout=2)
    if p.is_alive():
        p.terminate()
        p.join(timeout=2)
        pytest.fail(f"hung (infinite loop?) for is_simple_power({x!r}, {n!r})")
    assert not q.empty(), f"no result for ({x!r},{n!r})"
    kind, val = q.get()
    assert kind == "ok", f"raised {val} for ({x!r},{n!r})"
    assert val == expected, f"is_simple_power({x!r},{n!r})={val!r}, expected {expected!r}"


def test_n_zero_nonzero_is_false_no_hang_2():
    _assert_in_subprocess(2, 0, False)


def test_n_zero_nonzero_is_false_no_hang_3():
    _assert_in_subprocess(3, 0, False)


def test_n_zero_negative_is_false_no_hang():
    _assert_in_subprocess(-1, 0, False)


def test_n_zero_negative2_is_false_no_hang():
    _assert_in_subprocess(-5, 0, False)


# ---------- property tests (n != 0 to avoid hang in buggy impl) ----------
_nonzero_n = st.one_of(
    st.integers(min_value=-10, max_value=-2),
    st.sampled_from([-1, 1]),
    st.integers(min_value=2, max_value=10),
)

_small_x = st.integers(min_value=-1000, max_value=1000)


@given(_nonzero_n, _small_x)
def test_property_equivalence_to_reference(n, x):
    # order args as (x, n)
    assert is_simple_power(x, n) == ref(x, n)


@given(st.integers(min_value=2, max_value=5), st.integers(min_value=0, max_value=6))
def test_property_true_powers(n, k):
    x = n**k
    assert is_simple_power(x, n) == True


@given(st.integers(min_value=-5, max_value=-2), st.integers(min_value=0, max_value=8))
def test_property_true_powers_negative_base(n, k):
    x = n**k
    assert is_simple_power(x, n) == True


@given(st.integers(min_value=2, max_value=10))
def test_property_false_neighbors(n):
    # n**2 + 1 and n**2 - 1 are strictly between consecutive powers for n>=2
    # (n**1=n, n**2=n*n); check a value that cannot be a power
    k = 2
    for x in (n**k + 1, n**k - 1):
        # x==1 edge already true; skip it
        if x == 1:
            continue
        assert is_simple_power(x, n) == ref(x, n) == False


@given(st.integers(min_value=-100, max_value=100))
def test_property_minus_one_characterization(x):
    assert is_simple_power(x, -1) == (abs(x) == 1)


@given(st.integers(min_value=-100, max_value=100))
def test_property_one_characterization(x):
    assert is_simple_power(x, 1) == (x == 1)


@given(st.integers(min_value=-20, max_value=20))
def test_property_x_one_always_true(n):
    assert is_simple_power(1, n) == True


@given(st.integers(min_value=2, max_value=4), st.integers(min_value=-50, max_value=-1))
def test_property_negative_x_positive_n_is_false(n, x):
    # positive base can never give negative result with integer exponent
    # (negative exponents give positive fractions)
    assert is_simple_power(x, n) == False


@given(
    st.integers(min_value=2, max_value=5),
    st.integers(min_value=0, max_value=5),
    st.integers(min_value=2, max_value=5),
)
def test_property_monotonic_gap_false(n, k, d):
    # n**k < n**k + d <= n**(k+1) for small d implies false unless hits next power
    x = n**k + d
    if x == n ** (k + 1):
        return
    if x == 1:
        return
    # for d < n**(k+1)-n**k and d>0, x is strictly between powers
    if 0 < d < n ** (k + 1) - n**k:
        assert is_simple_power(x, n) == False
